#include <string>
#include <cstdint>

// Mock Slice for testing
class Slice {
public:
    Slice(const char* data, size_t size) : data_(data), size_(size) {}
    const char* data() const { return data_; }
    size_t size() const { return size_; }
private:
    const char* data_;
    size_t size_;
};

void AppendInternalKey(std::string* result, const Slice& user_key, uint64_t sequence, uint8_t type) {
    result->append(user_key.data(), user_key.size());
    uint64_t packed = (sequence << 8) | type;
    result->append(reinterpret_cast<const char*>(&packed), sizeof(packed));
}

// Test case
int main() {
    std::string result;
    Slice user_key("test_key", 8);
    uint64_t sequence = 123456;
    uint8_t type = 1;

    AppendInternalKey(&result, user_key, sequence, type);

    // Verify the result
    if (result.size() != 8 + sizeof(uint64_t)) {
        return 1; // Size mismatch
    }
    if (result.substr(0, 8) != "test_key") {
        return 1; // User key mismatch
    }

    // Verify packed value
    uint64_t packed;
    std::memcpy(&packed, result.data() + 8, sizeof(uint64_t));
    if (packed != ((sequence << 8) | type)) {
        return 1; // Packed value mismatch
    }

    return 0; // Success
}

